import{_ as l,l as n,o as i,c as r,v as m,p as d,x as e,d as o,i as p,S as g,b as t}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"sigmoid 注意力","description":"","frontmatter":{"title":"sigmoid 注意力","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sigmoid-attention.md","filePath":"llm/sigmoid-attention.md","lastUpdated":1789023840000}'),h={name:"llm/sigmoid-attention.md"};function f(u,a,c,x,_,A){const s=n("Mermaid");return i(),r("div",null,[a[1]||(a[1]=m('<h1 id="sigmoid-注意力" tabindex="-1">sigmoid 注意力 <a class="header-anchor" href="#sigmoid-注意力" aria-label="Permalink to &quot;sigmoid 注意力&quot;">​</a></h1><div class="epigraph"><p>用逐点 sigmoid 代替行 softmax，注意力不再在键之间做归一化竞争；每个键独立决定是否通过。</p><footer>—— Ramapuram et al., Theory, Analysis, and Best Practices for Sigmoid Self-Attention, 2024</footer></div><p><a href="/llm/gated-attention">上一课</a>在 softmax 之外加门，行和仍是 1。若问题本来就是「不该强制竞争」，门只是事后关幅度。本课把归一化换掉：分数经过逐点 \\(\\sigma\\)，输出是 \\(\\sigma(S)V\\)，不再沿键维做 softmax。后课再谈 sparsemax、softpick 等其它替代；本课只把 sigmoid 这条路走完，包括它必须补的尺度与归一。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/sdpa">SDPA</a> 的 softmax 做两件事：非负，以及一行内相对比较。相对比较带来尖峰与检索，也带来汇：全无关时质量仍要落到某列。门控能缩小写入，却不能让「所有键都不通过」。缺口是一种<strong>非竞争性</strong>的通过函数，使每个位置的通过率与其它键解耦，并在长序列上仍稳定。</p><p>Sigmoid 逐点把 logits 压到 \\((0,1)\\)，没有行和约束。代价立刻出现：没有竞争则没有自动的尺度校准，logits 漂移会让几乎所有门打开或关闭，输出范数随 \\(n\\) 涨。这是换核必须补的数值问题，不是实现细节。</p><p><span class="marginnote">线性注意力用核特征绕开 softmax，是另一条非竞争路线，见<a href="/llm/linear-attention">线性注意力</a>。Sigmoid 仍物化 \\(n\\times n\\) 分数，复杂度没降，变的是归一化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2> \\[\\mathrm{SigmoidAttn}(Q,K,V)=\\sigma\\!\\left(\\frac{QK^\\top}{\\tau}\\right)V, \\]<p>\\(\\tau\\) 为温度，常与 \\(\\sqrt{d_k}\\) 同类。因果掩码把非法位置的 \\(\\sigma\\) 置 0（或 logits 置大负数）。因为没有行归一化，Ramapuram 等人强调需要额外的稳定术：对 \\(Q,K\\) 做归一化、对输出按序列长度缩放（如乘 \\(1/n\\) 或 \\(1/\\sqrt{n}\\)）、或在块内做局部统计。缺其中一项，深度一加就容易激活爆炸。</p><p>实现上 sigmoid 可与 FlashAttention 一类分块核兼容，因为不再需要整行最大值与整行指数和——这是相对 softmax 的工程收益，不是表达力收益。</p><h3 id="与输出门并存时" tabindex="-1">与输出门并存时 <a class="header-anchor" href="#与输出门并存时" aria-label="Permalink to &quot;与输出门并存时&quot;">​</a></h3><p>上一课的门乘在 \\(u\\) 上；此处 \\(u\\) 本身已是非归一化通过。两条通路都在调幅度，消融时要分开看。默认配方是先换 sigmoid，再决定是否还要 GLU 式输出门。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>位置 \\(j\\) 对 \\(i\\) 的贡献是 \\(\\sigma(s_{ij})v_j\\)，不依赖 \\(s_{i,\\cdot}\\) 的其它项。多键可以同时以高权重通过，适合「若干证据都该写入」；也可能同时关闭，适合「这段与查询无关」。检索型的单峰对齐变弱，复制精确 token 的能力通常不如 softmax。</p><p>长度缩放把 \\(\\sum_j\\sigma(s_{ij})v_j\\) 的典型范数从随 \\(n\\) 线性涨拉回常数附近。它与后课的「注意力长度缩放」同源，但动机更硬：softmax 已有行和 1，sigmoid 没有。</p><p><span class="marginnote">温度 \\(\\tau\\) 在 sigmoid 里既管斜率又管通过率的先验。没有行内相对比较，调 \\(\\tau\\) 不再等价于 softmax 温度那种「更尖的单纯形」，而是「每个键更容易过 0.5」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>二次存储仍在，长上下文的内存问题原样保留。需要强竞争的归纳（精确拷贝、归纳头一类现象）可能变差。尺度技巧与架构耦合，迁移到已有 softmax 检查点不能只改一行激活。下一课的替代函数有的仍保持单纯形（sparsemax），有的完全离开概率解释；选 sigmoid 就是明确放弃「权重是分布」。</p>',19)),(i(),d(g,null,{default:e(()=>[p(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Query%22%5D%20--%3E%20S%5B%22%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%22%5D%0A%20%20K%5B%22Key%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20G%5B%22%E9%80%90%E7%82%B9%20sigmoid%22%5D%0A%20%20G%20--%3E%20N%5B%22%E6%8C%89%E9%95%BF%E5%BA%A6%E7%BC%A9%E6%94%BE%22%5D%0A%20%20N%20--%3E%20O%5B%22%E4%B9%98%20V%22%5D%0A%20%20V%5B%22Value%22%5D%20--%3E%20O%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"小结",tabindex:"-1"},[o("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=t("ul",null,[t("li",null,"Sigmoid 注意力用逐点通过代替行 softmax，键之间不再竞争，全无关时可以全部关闭。"),t("li",null,"必须补温度、QK 归一化或 \\(1/n\\) 类长度缩放，否则范数随序列膨胀。"),t("li",null,"复杂度仍是二次；收益是可分块、无行归约，以及非强制写入。"),t("li",null,"精确检索与归纳头一类依赖竞争的机制会变弱。"),t("li",null,"出处：Ramapuram et al., 2024。")],-1))])}const S=l(h,[["render",f]]);export{B as __pageData,S as default};
